-- Seed gerado por assets/gerador-avaliacao-discursiva (não editar à mão; fora do Git).
-- Rodar depois de database/2026-10-01-respostas-discursivas.sql. Idempotente.
-- A avaliação nasce BLOQUEADA (ativo = false): o professor libera no índice de atividades.
do $$
declare
  v_aula bigint;
  v_atividade bigint;
begin
  select a.id into v_aula from public.aulas a join public.materia m on m.id = a.materia_id
    where m.descricao = 'Análise de Dados Aplicada à Gestão' and a.numero = 4
    order by a.id limit 1;
  if v_aula is null then
    raise exception 'Aula 4 da matéria não encontrada';
  end if;

  insert into public.atividade (nome_atividade, status, aula_id, descricao, pagina,
      total_itens, ativo)
    values ('Prova Prática 06-10-2026', 'PENDENTE', v_aula, 'Atividade — Prova Prática 06-10-2026 (20 questões discursivas)',
      '/MATERIAIS/GESTAO_E_CONTROLE_MATERIAIS/ANALISE_DADOS_APLICADA_GESTAO/ATIVIDADES/PROVA-PRATICA-06-10-2026.html', 20, false)
    on conflict (pagina) do update set aula_id = excluded.aula_id,
      descricao = excluded.descricao, total_itens = excluded.total_itens
    returning id into v_atividade;

  delete from public.topico_discursivo where atividade_id = v_atividade;
  insert into public.topico_discursivo (atividade_id, item, topico, enunciado, pontos,
      resposta_esperada, criterios) values
      (v_atividade, 1, 1, 'Diga se as grandezas "rolos" e "dias" são diretamente ou inversamente proporcionais e monte a regra de três (a proporção entre as duas razões).', 0.1, '**Diretamente proporcionais** (mais dias de consumo, mais rolos). Proporção entre as razões: 900 rolos — 6 dias; x rolos — 30 dias → **900/6 = x/30**.', 'Palavras-chave: diretamente proporcional; 900 — 6; x — 30; igualdade de razões. Nota cheia (0,1): classifica como direta e monta a proporção. Metade (0,05): só uma das duas partes. Zero (0): classifica como inversa.'),
      (v_atividade, 1, 2, 'Calcule quantos rolos serão consumidos em 30 dias e quantas caixas do fornecedor atual devem ser compradas, mostrando as contas; explique o que fazer quando a divisão não dá um número exato e a que conjunto numérico pertence a quantidade de caixas.', 0.2, 'x = 900 × 30 ÷ 6 = **4.500 rolos** (150 rolos por dia × 30 dias). Caixas: 4.500 ÷ 40 = 112,5 → **113 caixas**: quando a divisão não é exata, **arredonda-se para cima**, porque não se compra meia caixa e arredondar para baixo deixaria faltar material. A quantidade de caixas é um **número natural (inteiro positivo)**, nunca racional/decimal.', 'Palavras-chave: 900 × 30 ÷ 6; 4.500 rolos; ÷ 40; 112,5; 113 caixas; arredondar para cima; números naturais/inteiros. Nota cheia (0,2): 4.500, 113 com o arredondamento justificado e o conjunto. Metade (0,1): contas certas sem justificar o arredondamento ou sem o conjunto. Zero (0): 112 caixas (arredonda para baixo) ou sem conta coerente.'),
      (v_atividade, 1, 3, 'Calcule o custo unitário (preço por rolo) de cada fornecedor, diga qual é mais barato e quanto a empresa economiza nos 4.500 rolos escolhendo o mais barato; faça uma estimativa para conferir se o resultado faz sentido.', 0.2, 'Atual: R$ 96,00 ÷ 40 = **R$ 2,40 por rolo**. Segundo fornecedor: R$ 138,00 ÷ 60 = **R$ 2,30 por rolo** → o segundo é **mais barato**. Economia nos 4.500 rolos: 4.500 × (2,40 − 2,30) = **R$ 450,00** (pelas caixas: 75 caixas × R$ 138 = R$ 10.350 contra 113 × R$ 96 = R$ 10.848, diferença de R$ 498 — também aceito). Estimativa: cerca de R$ 2 por rolo × 4.500 ≈ R$ 10.000, compatível com os totais.', 'Palavras-chave: preço por unidade; R$ 2,40; R$ 2,30; segundo fornecedor mais barato; economia R$ 450 (ou R$ 498 pelas caixas); estimativa/ordem de grandeza. Nota cheia (0,2): os dois preços unitários, a escolha, a economia e a conferência por estimativa. Metade (0,1): preços e escolha sem a economia, ou economia sem os preços unitários. Zero (0): compara só o preço da caixa (R$ 96 × R$ 138) e escolhe o atual.'),
      (v_atividade, 2, 1, 'Se o lote de 600 volumes fosse conferido por 10 conferentes, em quantas horas ficaria pronto? Diga se "conferentes" e "horas" são grandezas diretamente ou inversamente proporcionais e mostre a conta.', 0.1, 'Conferentes e horas são **inversamente proporcionais** (mais conferentes, menos horas). 5 × 6 = 10 × x → 30 = 10x → x = **3 horas**.', 'Palavras-chave: inversamente proporcional; 5 × 6 = 10 × x (produto constante); 3 horas. Equivalentes aceitos: "cai pela metade porque dobrou a equipe"; 30 horas-trabalho ÷ 10 = 3 h. Nota cheia (0,1): classifica como inversa e chega a 3 horas com conta. Metade (0,05): 3 horas sem classificar, ou classifica certo e erra a conta. Zero (0): classifica como direta ou responde 12 horas.'),
      (v_atividade, 2, 2, 'Monte a regra de três composta para o lote de 1.200 volumes em 4 horas: classifique "volumes" e "horas" em relação a "conferentes" (direta ou inversa), mostre a conta e dê o número de conferentes.', 0.2, 'Volumes × conferentes: **direta**. Horas × conferentes: **inversa**. x = 5 × (1.200 ÷ 600) × (6 ÷ 4) = 5 × 2 × 1,5 = **15 conferentes**.', 'Palavras-chave: volumes direta; horas inversa; inverter a razão das horas (6/4); 15 conferentes. Equivalentes aceitos: 5/x = (600/1.200) × (4/6); cálculo por conferente-hora (600 ÷ 30 = 20; 1.200 ÷ 20 = 60; 60 ÷ 4 = 15). Nota cheia (0,2): as duas classificações e 15 com conta. Metade (0,1): 15 sem classificar, ou classificações certas com erro de conta. Zero (0): trata horas como direta (≈ 7 conferentes) ou sem conta coerente.'),
      (v_atividade, 2, 3, 'Diga quantos conferentes precisam ser acrescentados à equipe atual de 5 e faça a prova real comparando a produtividade (volumes por conferente por hora) da situação atual com a da nova situação.', 0.2, 'Acrescentar 15 − 5 = **10 conferentes**. Prova real: atual = 600 ÷ (5 × 6) = **20 volumes por conferente por hora**; nova = 1.200 ÷ (15 × 4) = **20** → produtividade igual, cálculo confirmado.', 'Palavras-chave: 10 conferentes a mais; 20 volumes por conferente-hora nas duas situações; produtividade igual. Nota cheia (0,2): 10 conferentes e a prova real com os dois valores iguais. Metade (0,1): só os 10 ou só a prova real. Zero (0): responde 15 a acrescentar sem prova real.'),
      (v_atividade, 3, 1, 'Calcule a área útil do galpão (descontando o corredor) e a área de um palete, com as unidades.', 0.1, 'Área útil = 20 m × (12 m − 2 m) = **200 m²**. Área do palete = 1,2 m × 1,0 m = **1,2 m²**.', 'Palavras-chave: descontar o corredor; 200 m²; 1,2 m²; comprimento × largura. Nota cheia (0,1): as duas áreas com unidade. Metade (0,05): uma área certa, ou as duas sem descontar o corredor (240 m²). Zero (0): sem conta coerente.'),
      (v_atividade, 3, 2, 'Calcule o volume de uma caixa em m³ e em litros e o peso de um palete com 24 caixas em kg (convertendo de gramas), dizendo se ele respeita o limite de 1.000 kg.', 0.2, 'Volume = 0,40 × 0,35 × 0,25 = **0,035 m³** = 0,035 × 1.000 = **35 L**. Peso: 35.000 g ÷ 1.000 = **35 kg**; palete: 24 × 35 = **840 kg**, abaixo de 1.000 kg → **respeita o limite**.', 'Palavras-chave: comprimento × largura × altura; 0,035 m³; 35 L; ÷ 1.000; 35 kg; 840 kg; respeita. Equivalentes aceitos: cálculo em cm (35.000 cm³ = 35 L). Nota cheia (0,2): volume, litros, peso e conclusão. Metade (0,1): só a parte do volume ou só a do peso certa. Zero (0): conversões erradas (3,5 L, 3,5 kg) levando a conclusão errada.'),
      (v_atividade, 3, 3, 'Mostre, pelo arranjo, quantas caixas cabem no palete (quantas no sentido de 1,2 m, quantas no de 1,0 m e quantas camadas) e explique por que a divisão do volume do palete pelo volume da caixa daria um número maior que não pode ser usado.', 0.2, 'Arranjo: 1,2 ÷ 0,40 = **3**; 1,0 ÷ 0,35 = 2,85 → **2**; 1,2 ÷ 0,25 = 4,8 → **4 camadas** → 3 × 2 × 4 = **24 caixas**. Pela divisão de volumes: 1,44 m³ ÷ 0,035 ≈ **41 caixas**, número teórico que não serve porque **as sobras de espaço não formam caixas inteiras** (não se corta caixa); vale o arranjo.', 'Palavras-chave: 3 × 2 × 4; 24 caixas; arredondar para baixo em cada direção; sobra não vira caixa; ≈ 41 pela divisão. Nota cheia (0,2): arranjo, 24 caixas e explicação das sobras. Metade (0,1): 24 sem explicar a divisão, ou explicação certa com erro numa direção. Zero (0): responde 41 como final, ou arredonda para cima (45).'),
      (v_atividade, 4, 1, 'Calcule a variação percentual do estoque de capacetes, mostrando a fórmula (valor final − valor inicial) ÷ valor inicial, e diga se foi aumento ou queda.', 0.1, '(210 − 250) ÷ 250 = −40 ÷ 250 = −0,16 → **queda de 16%**.', 'Palavras-chave: (final − inicial) ÷ inicial; −40; ÷ 250; queda de 16%. Nota cheia (0,1): conta e resultado com o sentido. Metade (0,05): 16% sem dizer queda, ou erro de cálculo com a conta certa. Zero (0): divide pelo valor final (≈ −19%) ou dá 40%/84%.'),
      (v_atividade, 4, 2, 'Calcule o lucro por capacete, a margem sobre a receita (preço de venda) e a margem sobre o custo, e explique por que os dois percentuais são diferentes.', 0.2, 'Lucro = 50 − 40 = **R$ 10,00**. Margem sobre a receita = 10 ÷ 50 = **20%**. Margem sobre o custo = 10 ÷ 40 = **25%**. São diferentes porque a **base de cálculo é diferente**: calcular 20% sobre o custo não garante 20% de margem sobre o preço de venda (formação de preço).', 'Palavras-chave: R$ 10,00; 20% sobre a receita; 25% sobre o custo; base diferente. Equivalentes aceitos: "markup" para a margem sobre o custo. Nota cheia (0,2): os três valores e a explicação. Metade (0,1): valores sem explicação, ou um percentual certo com a explicação. Zero (0): troca as bases sem nenhum valor certo.'),
      (v_atividade, 4, 3, 'Calcule o preço final das luvas usando os fatores multiplicativos (aumento e desconto), a variação real em porcentagem e explique por que o colega errou.', 0.2, 'Aumento: 80 × **1,15** = R$ 92,00; desconto: 92 × **0,96** = **R$ 88,32**. Fator total 1,15 × 0,96 = 1,104 → aumento real de **10,4%**. O colega errou porque **percentuais sucessivos se multiplicam** como fatores (o desconto incide sobre o preço já aumentado), não se somam nem se subtraem.', 'Palavras-chave: fatores 1,15 e 0,96; R$ 88,32; 1,104; 10,4%; percentuais sucessivos se multiplicam. Nota cheia (0,2): preço final, 10,4% e a explicação. Metade (0,1): duas das três partes. Zero (0): concorda com os 11%.'),
      (v_atividade, 5, 1, 'Calcule a média das saídas, mostrando a soma e a divisão.', 0.1, 'Soma = 20 + 22 + 22 + 25 + 26 + 105 = 220; média = 220 ÷ 6 ≈ **36,67 caixas por dia**.', 'Palavras-chave: soma 220; dividir por 6; 36,67. Nota cheia (0,1): soma, divisão e resultado. Metade (0,05): conta certa com erro pequeno. Zero (0): sem conta coerente.'),
      (v_atividade, 5, 2, 'Calcule a mediana (mostrando o rol em ordem) e diga qual é a moda; depois, calcule a frequência relativa (%) de cada resposta da pesquisa.', 0.2, 'Rol: 20, 22, 22, 25, 26, 105 (6 valores, par) → mediana = (22 + 25) ÷ 2 = **23,5 caixas**; moda = **22**. Frequência relativa da pesquisa: Excelente 80 ÷ 200 = **40%**; Bom 70 ÷ 200 = **35%**; Regular 30 ÷ 200 = **15%**; Ruim 20 ÷ 200 = **10%** (soma 100%).', 'Palavras-chave: rol em ordem; média dos dois centrais; 23,5; moda 22; frequência relativa = absoluta ÷ total; 40%, 35%, 15%, 10%. Nota cheia (0,2): mediana, moda e as quatro frequências relativas. Metade (0,1): só a parte estatística (mediana e moda) ou só as frequências certas. Zero (0): nenhuma das partes.'),
      (v_atividade, 5, 3, 'Diga qual medida representa melhor o consumo típico do almoxarifado e justifique usando o dia atípico.', 0.2, 'A **mediana (23,5)** representa melhor o consumo típico. O dia atípico de 105 caixas **puxa a média para cima** (36,67), e comprar pela média geraria excesso de estoque; a mediana é **resistente a valores extremos**.', 'Palavras-chave: mediana; valor atípico (extremo, outlier); puxa a média; resistente; excesso de compra. Nota cheia (0,2): escolhe a mediana e justifica pelo valor atípico. Metade (0,1): escolhe a mediana sem justificar bem. Zero (0): escolhe a média.'),
      (v_atividade, 6, 1, 'Calcule a média e a amplitude dos prazos de cada transportadora, mostrando as contas.', 0.1, 'Rota Certa: média = 20 ÷ 5 = **4 dias**; amplitude = 5 − 3 = **2 dias**. Via Rápida: média = 20 ÷ 5 = **4 dias**; amplitude = 7 − 1 = **6 dias**.', 'Palavras-chave: soma 20; ÷ 5; média 4 nas duas; amplitude 2 e 6; maior − menor. Nota cheia (0,1): as duas médias e amplitudes. Metade (0,05): só as médias ou só as amplitudes. Zero (0): nenhum valor certo.'),
      (v_atividade, 6, 2, 'Calcule a variância (dividindo por 5) e o desvio padrão de cada transportadora e diga qual escolher, explicando o que aconteceria com o estoque de segurança se a escolha considerasse só a média.', 0.2, 'Rota Certa: quadrados dos desvios 1, 0, 1, 1, 1 → soma 4 → variância **0,8** → DP ≈ **0,89 dia**. Via Rápida: 9, 9, 4, 4, 0 → soma 26 → variância **5,2** → DP ≈ **2,28 dias**. Escolher a **Rota Certa**: mesma média, **desvio padrão menor**, mais previsível. Olhando só a média elas pareceriam iguais; com a Via Rápida seria preciso **estoque de segurança maior** para não faltar material (ruptura).', 'Palavras-chave: desvios ao quadrado; soma 4 e 26; variância 0,8 e 5,2; raiz; 0,89 e 2,28; Rota Certa; previsível; estoque de segurança maior. Equivalentes aceitos: =DESVPAD.P com os mesmos resultados. Nota cheia (0,2): cálculos das duas e escolha justificada com o estoque de segurança. Metade (0,1): cálculos certos sem a decisão, ou decisão certa com cálculo incompleto (ou dividido por 4). Zero (0): escolhe a Via Rápida ou usa a amplitude como desvio padrão sem decisão certa.'),
      (v_atividade, 6, 3, 'Diga qual meta é uma PA e qual é uma PG (com a razão de cada uma), calcule quantos pedidos cada meta prevê para o 4º mês, contando 200 pedidos como o 1º mês, diga qual cresce mais rápido e por quê, e cite um risco (hipótese pessimista, de causa e efeito) de adotar a meta que cresce mais sem analisar a capacidade da equipe e do estoque.', 0.2, 'Meta A = **PA** de razão **+40**: 200, 240, 280, **320** no 4º mês. Meta B = **PG** de razão **1,2** (+20%): 200, 240, 288, **345,6 ≈ 346**. A **PG cresce mais rápido** porque **multiplica** (os 20% incidem sobre um valor que já aumentou), enquanto a PA soma sempre o mesmo valor. Risco (hipótese pessimista): a equipe e o estoque podem **não acompanhar** o crescimento da PG (atrasos, falta de material, horas extras) e a demanda pode não se confirmar; correlação não garante causalidade, então é preciso analisar os fatores operacionais antes de adotar a meta.', 'Palavras-chave: PA; razão 40; 320; PG; razão 1,2; 345,6 ou 346; multiplicação × soma fixa; risco/hipótese pessimista; capacidade da equipe ou do estoque. Nota cheia (0,2): PA/PG com razões, valores, justificativa e um risco coerente. Metade (0,1): cálculos certos sem justificativa ou sem risco; ou um valor errado com o resto certo. Zero (0): inverte PA e PG sem parte certa.'),
      (v_atividade, 7, 1, 'Explique o que significa um número aparecer alinhado à esquerda (tipo de dado), diga em que parte da interface se confere o conteúdo exato da célula ativa e escreva a fórmula do custo em estoque em D2 (quantidade × custo unitário).', 0.1, 'Número alinhado à esquerda foi **interpretado como texto** (números e datas ficam à direita; textos à esquerda) e **não entra nas contas**. O conteúdo exato da célula ativa (valor ou fórmula) é conferido na **Barra de Fórmulas**, logo abaixo da Faixa de Opções. D2: **=B2*C2**.', 'Palavras-chave: texto à esquerda; número à direita; não calcula; Barra de Fórmulas; =B2*C2. Nota cheia (0,1): explicação, Barra de Fórmulas e fórmula. Metade (0,05): duas das três partes. Zero (0): uma ou nenhuma.'),
      (v_atividade, 7, 2, 'Escreva a fórmula da armazenagem em E2 (custo em estoque × taxa de H1), de modo que possa ser arrastada até a linha 40 sem erro, diga a tecla que insere os cifrões e explique por que, se o colega usar =D2*H1 e arrastar, E3 mostra zero.', 0.2, 'E2: **=D2*$H$1** — tecla **F4** insere os cifrões (referência absoluta). Com =D2*H1 arrastado, E3 vira **=D3*H2**: a **referência relativa andou** e H2 está **vazia** (vale 0), então o resultado é zero.', 'Palavras-chave: =D2*$H$1; referência absoluta; F4; =D3*H2; referência relativa anda; H2 vazia. Equivalentes aceitos: =D2*H$1; =B2*C2*$H$1. Nota cheia (0,2): fórmula travada, F4 e a explicação do zero. Metade (0,1): duas das três partes. Zero (0): fórmula sem trava e sem explicação.'),
      (v_atividade, 7, 3, 'Para o custo com frete (quantidade × (custo unitário + frete)), o colega escreveu =B2*C2+F2. Calcule o resultado da fórmula dele e o resultado correto para a linha 2, escreva a fórmula correta e explique a regra de precedência que causou o erro.', 0.2, 'Colega: =B2*C2+F2 = 10 × 8 + 2 = **82**. Correto: **=B2*(C2+F2)** = 10 × 10 = **100**. **Precedência**: o Excel faz multiplicação antes da soma; os **parênteses** forçam a soma primeiro.', 'Palavras-chave: 82; 100; =B2*(C2+F2); multiplicação antes da adição; parênteses. Equivalentes aceitos: =(C2+F2)*B2; =B2*C2+B2*F2. Nota cheia (0,2): os dois resultados, a fórmula e a regra. Metade (0,1): fórmula e 100 sem o 82 ou sem a regra. Zero (0): diz que a fórmula do colega está certa.'),
      (v_atividade, 8, 1, 'Escreva as fórmulas de SOMA e de MÉDIA das saídas (B2:B7) e informe os dois resultados, explicando como a célula vazia afeta a média.', 0.1, '**=SOMA(B2:B7)** → **90**. **=MÉDIA(B2:B7)** → 90 ÷ 5 = **18**. A célula vazia é **ignorada no divisor** (divide por 5; se tivesse 0 digitado, a média seria 15).', 'Palavras-chave: SOMA; 90; MÉDIA; 18; vazia não conta; divide por 5. Nota cheia (0,1): fórmulas, resultados e explicação. Metade (0,05): resultados sem explicar, ou explicação com um resultado errado. Zero (0): média 15 dizendo que a vazia conta como zero.'),
      (v_atividade, 8, 2, 'Escreva as fórmulas e informe os resultados de CONT.NÚM(B2:B7), CONT.VALORES(A2:A7) e da amplitude das saídas usando MÁXIMO e MÍNIMO. Explique a diferença entre CONT.NÚM e CONT.VALORES.', 0.2, '**=CONT.NÚM(B2:B7) → 5**; **=CONT.VALORES(A2:A7) → 6**; **=MÁXIMO(B2:B7)-MÍNIMO(B2:B7) → 30 − 6 = 24**. CONT.NÚM conta **só números**; CONT.VALORES conta **qualquer célula preenchida**.', 'Palavras-chave: 5; 6; MÁXIMO − MÍNIMO; 24; só números × qualquer célula preenchida. Nota cheia (0,2): três resultados com fórmulas e a diferença. Metade (0,1): dois resultados com a diferença, ou três sem a diferença. Zero (0): funções trocadas sem outra parte certa.'),
      (v_atividade, 8, 3, 'Escreva em G2 a fórmula com SE que mostra "Repor" quando o saldo for menor que o mínimo e "OK" nos outros casos, cite o operador de comparação usado e informe o resultado para saldo 15 e mínimo 20 e para saldo 20 e mínimo 20, justificando o segundo caso.', 0.2, 'G2: **=SE(E2<F2;"Repor";"OK")**, com o operador de comparação **< (menor que)**. Saldo 15/mínimo 20 → **"Repor"**. Saldo 20/mínimo 20 → **"OK"**, porque 20 **não é menor** que 20 (teste FALSO → valor_se_falso).', 'Palavras-chave: =SE(E2<F2;"Repor";"OK"); operador <; aspas; Repor; OK; 20<20 é falso. Equivalentes aceitos: =SE(E2>=F2;"OK";"Repor"). Nota cheia (0,2): fórmula, operador, resultados e justificativa do empate. Metade (0,1): fórmula e resultados sem justificar o empate. Zero (0): usa <= (Repor para 20 e 20) sem justificativa correta.'),
      (v_atividade, 9, 1, 'Escreva a fórmula do Saldo em E2 e diga como levá-la de uma vez até a linha 300 usando a alça de preenchimento.', 0.1, 'E2: **=C2-D2**. Levar até a linha 300: **duplo clique na alça de preenchimento** (quadradinho no canto inferior direito da célula), que propaga até a última linha preenchida da tabela ao lado (ou clicar e arrastar a alça até a linha 300).', 'Palavras-chave: =C2-D2; alça de preenchimento; canto inferior direito; duplo clique ou arrastar. Nota cheia (0,1): fórmula e uso da alça. Metade (0,05): só uma das partes. Zero (0): nenhuma.'),
      (v_atividade, 9, 2, 'Explique o que acontece com a fórmula do Saldo ao ser copiada para E3 (referência relativa) e como gerar a sequência "Jan" a "Dez" no cabeçalho com a alça.', 0.2, 'Em E3 a fórmula vira **=C3-D3**: a **referência relativa se ajusta à linha** ao ser copiada, por isso cada linha calcula o próprio saldo. Sequência: digitar "Jan" em H1 e **arrastar a alça** para a direita; o Excel **gera a sequência lógica** Fev, Mar... até Dez.', 'Palavras-chave: =C3-D3; referência relativa se ajusta/anda; cada linha o próprio saldo; arrastar a alça; sequência de meses. Nota cheia (0,2): as duas partes. Metade (0,1): só uma delas. Zero (0): diz que a fórmula continua =C2-D2 e não explica a sequência.'),
      (v_atividade, 9, 3, 'Explique como separar o código (ex.: "MAT-001") na coluna B usando o Preenchimento Relâmpago (com o atalho) e o que o Excel faz com as outras linhas.', 0.2, 'Digitar em B2 o código da primeira linha ("MAT-001") e usar o **Preenchimento Relâmpago** (**Ctrl+E**, ou Dados > Preenchimento Relâmpago): o Excel **reconhece o padrão** do exemplo e **preenche as outras linhas sozinho**, separando o código de cada texto.', 'Palavras-chave: digitar um exemplo; Preenchimento Relâmpago; Ctrl+E; reconhece o padrão; preenche as demais linhas. Equivalentes aceitos: no LibreOffice, usar Texto para Colunas com o espaço como separador (aceitar se explicado). Nota cheia (0,2): exemplo, recurso com atalho e o que o Excel faz. Metade (0,1): cita o recurso sem o atalho ou sem explicar o padrão. Zero (0): propõe digitar todos os códigos à mão.'),
      (v_atividade, 10, 1, 'Descreva o caminho e escreva a fórmula da regra de formatação condicional que pinta de vermelho o saldo (E2:E500) quando estiver abaixo do mínimo e explique por que o cifrão fica só na coluna.', 0.1, 'Selecionar **E2:E500** → **Página Inicial > Formatação Condicional > Nova Regra > Usar uma fórmula** → **=$E2<$F2** → preenchimento **vermelho**. O cifrão **só na coluna** deixa a linha variar, e cada item é comparado com o **próprio mínimo**.', 'Palavras-chave: Formatação Condicional; Nova Regra; usar fórmula; =$E2<$F2; vermelho; linha varia. Nota cheia (0,1): caminho, fórmula e explicação do $. Metade (0,05): caminho e fórmula sem o $ explicado, ou fórmula e explicação sem o caminho. Zero (0): pinta à mão ou usa =$E$2<$F$2.'),
      (v_atividade, 10, 2, 'Descreva a validação de dados que obriga a escolher o código de uma lista ligada ao Cadastro (caminho, opção "Permitir", fonte travada e estilo do alerta) e a validação que só aceita quantidades inteiras de 1 a 200.', 0.2, 'Código: selecionar **A2:A500** → **Dados > Validação de Dados** → **Permitir: Lista** → **Fonte: =Cadastro!$A$2:$A$250** → alerta estilo **Parar**. Quantidade: selecionar **C2:C500** → Validação de Dados → **Permitir: Número inteiro** → **entre 1 e 200** → alerta **Parar**.', 'Palavras-chave: Dados; Validação de Dados; Lista; =Cadastro!$A$2:$A$250; Parar; Número inteiro; entre 1 e 200. Nota cheia (0,2): as duas validações completas. Metade (0,1): uma completa, ou as duas sem a fonte travada/o alerta. Zero (0): propõe formatação condicional no lugar de validação.'),
      (v_atividade, 10, 3, 'Diga qual recurso visual da formatação condicional (Escalas de Cor ou Barras de Dados) usar na coluna H para destacar os maiores valores, como ele funciona e por que validar a entrada evita erros nos relatórios e nas buscas com PROCV.', 0.2, 'Usar **Barras de Dados** (gráfico horizontal dentro da célula, maior barra = maior valor) ou **Escalas de Cor** (gradiente, ex.: verde a vermelho, mostrando o "calor" dos valores) — **Página Inicial > Formatação Condicional > Barras de Dados/Escalas de Cor**. Validar a entrada evita erros porque **dados errados geram somas, contagens e saldos errados**, e um **código inexistente faria o PROCV retornar #N/D**; o erro é barrado antes de entrar.', 'Palavras-chave: Barras de Dados ou Escalas de Cor; tamanho da barra/gradiente de cor; formatação condicional; dados errados → relatórios errados; #N/D no PROCV. Nota cheia (0,2): recurso visual explicado e a justificativa da validação. Metade (0,1): só uma das partes. Zero (0): nenhuma.'),
      (v_atividade, 11, 1, 'Explique o problema de digitar "R$" dentro da célula e o que fazer no lugar, e explique por que apareceu 1200% e como digitar 12% corretamente.', 0.1, 'Com "R$" digitado a célula vira **texto** e **não calcula**; digitar só o número (**1250**) e aplicar o formato **Moeda/Contábil** (o formato muda só a exibição). Apareceu **1200%** porque o formato de porcentagem **multiplica por 100**; digitar **0,12** e aplicar %, ou digitar **12%** direto.', 'Palavras-chave: vira texto; não calcula; formato Moeda/Contábil; só exibição; multiplica por 100; 0,12 ou 12%. Nota cheia (0,1): as duas explicações com correções. Metade (0,05): só uma situação. Zero (0): nenhuma.'),
      (v_atividade, 11, 2, 'Escreva a fórmula do vencimento do pagamento (data de B2 + 30 dias), informe a data resultante e explique por que somar números a uma data funciona; diga também qual das três opções de congelamento usar para manter visíveis, ao mesmo tempo, a linha 1 e a coluna A (e em qual célula clicar).', 0.2, '**=B2+30** → **14/11/2026**. Funciona porque, no Excel, **toda data é um número sequencial de dias**; somar 30 avança 30 dias. Para manter a linha 1 e a coluna A: clicar em **B2** → **Exibir > Congelar Painéis > Congelar Painéis** (a opção livre; "Congelar Linha Superior" só fixa a linha 1 e "Congelar Primeira Coluna" só a coluna A).', 'Palavras-chave: =B2+30; 14/11/2026; data é número de dias; B2; Exibir; Congelar Painéis (livre). Nota cheia (0,2): fórmula, data, explicação e congelamento certo. Metade (0,1): fórmula/data certas sem o congelamento certo, ou congelamento certo com data errada. Zero (0): data e congelamento errados.'),
      (v_atividade, 11, 3, 'Descreva como usar o AutoFiltro para mostrar só os custos maiores que R$ 1.000,00, ordenados do maior para o menor, e diga o que acontece com as linhas que não aparecem.', 0.2, '**Dados > Filtro** (ou **Ctrl+Shift+L**) → seta da coluna do custo → **Filtros de Número > É Maior do que → 1000** → **Classificar do Maior para o Menor**. As linhas que não atendem ficam **apenas ocultas, não são apagadas**: ao limpar o filtro, voltam.', 'Palavras-chave: AutoFiltro/Ctrl+Shift+L; Filtros de Número; maior que 1.000; classificar do maior para o menor; linhas ocultas, não apagadas. Nota cheia (0,2): filtro, ordenação e o que acontece com as linhas. Metade (0,1): dois dos três. Zero (0): um ou nenhum.'),
      (v_atividade, 12, 1, 'Cite três ajustes de estilo para o relatório ficar profissional (fonte, alinhamento de textos e números, cabeçalho e linha de total).', 0.1, 'Três destes ajustes: **uma única família de fontes** limpa (Calibri, Aptos, Segoe UI); **textos à esquerda e números/moedas à direita**; **cabeçalho escuro com texto branco** e linhas de grade discretas; **linha de total em negrito com borda dupla inferior**.', 'Palavras-chave: uma fonte; textos à esquerda, números à direita; cabeçalho escuro/contraste; total em negrito/borda dupla. Nota cheia (0,1): três ajustes. Metade (0,05): dois ajustes. Zero (0): um ou nenhum.'),
      (v_atividade, 12, 2, 'Explique, na ordem, as duas etapas para proteger as fórmulas e ainda deixar a equipe digitar nas colunas C e D.', 0.2, 'Etapa 1: selecionar as colunas **C e D** → **Formatar Células (Ctrl+1) > aba Proteção > desmarcar "Bloqueadas"** (por padrão todas as células estão bloqueadas). Etapa 2: **Revisão > Proteger Planilha** (senha opcional). As fórmulas ficam travadas e C e D continuam editáveis.', 'Palavras-chave: destravar C e D; desmarcar Bloqueadas; Ctrl+1/Proteção; Revisão; Proteger Planilha; ordem certa. Nota cheia (0,2): as duas etapas na ordem. Metade (0,1): só Proteger Planilha sem destravar, ou ordem invertida. Zero (0): não descreve proteção.'),
      (v_atividade, 12, 3, 'Explique a diferença entre Proteger Planilha e Proteger Estrutura da Pasta, diga qual delas evita que a aba "Cadastro" seja excluída e para que serve a senha.', 0.2, '**Proteger Planilha** impede editar células, fórmulas ou formatação **da aba atual**; **Proteger Estrutura da Pasta** impede **excluir, renomear ou adicionar abas** no arquivo. A que evita excluir a aba "Cadastro" é a **Proteger Estrutura da Pasta** (Revisão > Proteger Pasta de Trabalho). A **senha** impede que outra pessoa **desative a proteção** sem autorização.', 'Palavras-chave: Proteger Planilha = células da aba; Proteger Estrutura da Pasta = abas; Proteger Pasta de Trabalho; senha impede desproteger. Nota cheia (0,2): a diferença, a escolha certa e o papel da senha. Metade (0,1): dois dos três. Zero (0): diz que Proteger Planilha impede excluir a aba, sem outra parte certa.'),
      (v_atividade, 13, 1, 'Escreva as fórmulas com PROCV para a descrição (C2) e para o preço (D2), com a matriz travada e busca exata, e explique o número da coluna e o último argumento 0.', 0.1, 'C2: **=PROCV(A2;Cadastro!$A$2:$D$401;2;0)** (coluna 2 = Descrição). D2: **=PROCV(A2;Cadastro!$A$2:$D$401;4;0)** (coluna 4 = Preço, contando a partir da 1ª coluna da matriz). O **0** força a **busca exata** e os cifrões travam a matriz.', 'Palavras-chave: PROCV; A2; Cadastro!$A$2:$D$401; 2; 4; 0 exato; coluna contada a partir da 1ª. Nota cheia (0,1): as duas fórmulas e a explicação. Metade (0,05): fórmulas sem explicar, ou sem $/sem o 0 com a explicação certa. Zero (0): número de coluna errado nas duas.'),
      (v_atividade, 13, 2, 'Escreva a fórmula do preço protegida com SEERRO devolvendo 0 e a fórmula do total em E2. Explique por que, no preço, é melhor devolver 0 do que um texto.', 0.2, 'D2: **=SEERRO(PROCV(A2;Cadastro!$A$2:$D$401;4;0);0)**. E2: **=B2*D2**. No preço é melhor devolver **0** porque é um campo numérico: com texto, o total e as somas dariam erro (**#VALOR!**); com 0 a planilha continua calculando.', 'Palavras-chave: SEERRO envolvendo o PROCV; devolve 0; =B2*D2; texto quebra as contas/#VALOR!. Nota cheia (0,2): fórmulas e justificativa. Metade (0,1): fórmulas sem justificar, ou justificativa com SEERRO devolvendo texto. Zero (0): SEERRO usado de forma inválida, sem justificativa.'),
      (v_atividade, 13, 3, 'O código 1015 existe no cadastro, mas a busca dele retorna #N/D. Explique duas causas possíveis e como corrigir cada uma.', 0.2, 'Duas destas causas com a correção: (1) código **salvo como texto** (alinhado à esquerda, triângulo verde) → converter em número ou **=VALOR(A2)**; conferir com **=ÉTEXTO(A2)**; (2) **espaço extra** ("1015 ") → **=ARRUMAR(A2)**; (3) **matriz sem cifrão** que andou ao arrastar → travar **$A$2:$D$401**.', 'Palavras-chave: número como texto; VALOR/ÉTEXTO; espaço extra; ARRUMAR; matriz sem $. Nota cheia (0,2): duas causas com correções. Metade (0,1): uma causa com correção, ou duas sem correções. Zero (0): só "usar SEERRO" (esconde, não corrige).'),
      (v_atividade, 14, 1, 'Escreva a fórmula com PROCH que traz a tarifa de "Março" da Via Rápida (matriz travada e busca exata) e explique quando se usa PROCH em vez de PROCV.', 0.1, '**=PROCH("Março";$A$1:$M$3;3;0)** (ou matriz $B$1:$M$3). Usa-se **PROCH** quando a chave está na **primeira linha** da tabela, com os períodos (meses) **lado a lado no topo** (busca horizontal); o PROCV procura na primeira **coluna** (busca vertical).', 'Palavras-chave: PROCH; "Março"; matriz travada; linha 3; 0 exato; chave na primeira linha/horizontal. Nota cheia (0,1): fórmula e explicação. Metade (0,05): só uma das partes, ou índice de linha errado. Zero (0): usa PROCV sem justificativa.'),
      (v_atividade, 14, 2, 'Escreva a fórmula com ÍNDICE + CORRESP que traz o nome do fornecedor a partir do código em K2 e explique por que o PROCV não resolve essa busca.', 0.2, '**=ÍNDICE($G$2:$G$20;CORRESP(K2;$H$2:$H$20;0))**. O PROCV não resolve porque **só procura na primeira coluna da matriz e devolve dados à direita**; aqui o nome está **à esquerda** do código.', 'Palavras-chave: ÍNDICE; CORRESP; G2:G20 resultado; H2:H20 código; 0; PROCV só para a direita. Nota cheia (0,2): fórmula e explicação. Metade (0,1): fórmula sem explicar, ou explicação com intervalos trocados. Zero (0): diz que o PROCV resolve.'),
      (v_atividade, 14, 3, 'Explique o que cada função faz sozinha (o que CORRESP devolve e o que ÍNDICE devolve) e cite duas situações em que é melhor usar ÍNDICE + CORRESP do que PROCV.', 0.2, '**CORRESP** devolve a **posição (número da linha)** do valor procurado na lista (ex.: =CORRESP("Cometa";A2:A5;0) → 3); **ÍNDICE** devolve o **conteúdo** da célula naquela posição do intervalo. Usar ÍNDICE + CORRESP quando: a coluna pesquisada está **à direita** do resultado (busca para a esquerda); em **bases grandes, onde inserir colunas quebra o número de coluna do PROCV**; em **buscas em linhas e colunas** (bidirecionais); por **velocidade** em milhares de linhas.', 'Palavras-chave: CORRESP = posição; ÍNDICE = conteúdo da posição; busca à esquerda; inserir colunas não quebra; bidirecional; velocidade. Nota cheia (0,2): papel das duas funções e duas situações. Metade (0,1): só os papéis ou só as situações. Zero (0): nenhuma.'),
      (v_atividade, 15, 1, 'Escreva em F2 a fórmula com SE aninhado que classifica o valor total (E2): 5.000 ou mais = "Alta"; de 1.000 até 4.999,99 = "Média"; abaixo de 1.000 = "Baixa", e explique por que os testes começam pelo maior valor.', 0.1, '**=SE(E2>=5000;"Alta";SE(E2>=1000;"Média";"Baixa"))**. Os testes começam pelo **maior valor** porque o SE **para no primeiro teste verdadeiro**: começando por >=1000, um valor de 5.000 já seria "Média" e as condições se anulariam.', 'Palavras-chave: SE dentro de SE; >=5000; >=1000; Alta, Média, Baixa; para no primeiro verdadeiro. Equivalentes aceitos: ordem crescente com "<" bem explicada. Nota cheia (0,1): fórmula e explicação. Metade (0,05): fórmula sem explicar, ou explicação com erro de limite. Zero (0): SE simples com duas saídas.'),
      (v_atividade, 15, 2, 'Escreva a fórmula que conta as requisições da categoria "EPI" e a que conta as requisições com valor total acima da média (usando o & no critério), explicando o papel do &.', 0.2, '**=CONT.SE(C2:C301;"EPI")**. Acima da média: **=CONT.SE(E2:E301;">"&MÉDIA(E2:E301))**. O **&** **concatena (junta)** o operador ">" com o número calculado pela MÉDIA, formando o critério; escrito tudo entre aspas, a função não seria calculada.', 'Palavras-chave: CONT.SE; "EPI" entre aspas; ">"&MÉDIA; & concatena/junta. Equivalentes aceitos: colunas inteiras. Nota cheia (0,2): as duas fórmulas e o papel do &. Metade (0,1): só uma fórmula com a explicação, ou as duas sem explicar. Zero (0): usa SOMASE ou sem critério.'),
      (v_atividade, 15, 3, 'Escreva a fórmula que soma o valor total da categoria "Ferramentas", explique o papel de cada intervalo e a diferença entre a pergunta que o CONT.SE responde e a que o SOMASE responde.', 0.2, '**=SOMASE(C2:C301;"Ferramentas";E2:E301)**: C2:C301 é o **intervalo do critério** (onde procura a categoria), "Ferramentas" é o **critério** e E2:E301 é o **intervalo somado**; os dois intervalos têm o **mesmo número de linhas**. O **CONT.SE** responde **"quantas vezes?"** e o **SOMASE** responde **"quanto gerou/somou?"**.', 'Palavras-chave: SOMASE; intervalo do critério; critério entre aspas; intervalo de soma; mesmo tamanho; quantas vezes × quanto. Nota cheia (0,2): fórmula, papel dos intervalos e a diferença. Metade (0,1): dois dos três. Zero (0): usa CONT.SE para somar.'),
      (v_atividade, 16, 1, 'Diga os dois problemas da base que atrapalham a tabela dinâmica e como corrigir cada um.', 0.1, '(1) **Células mescladas** no cabeçalho quebram a tabela dinâmica → desfazer a mesclagem e deixar **um nome único em cada coluna**; (2) **linha em branco** parte a seleção → **excluir a linha 601**. (Uma informação por coluna.)', 'Palavras-chave: células mescladas; desmesclar/cabeçalho único; linha em branco corta a seleção; excluir. Nota cheia (0,1): os dois problemas com correção. Metade (0,05): um problema com correção. Zero (0): nenhum.'),
      (v_atividade, 16, 2, 'Diga o caminho para criar a tabela dinâmica, em qual área (Linhas, Colunas, Valores ou Filtros) entra cada campo para ver o valor comprado por fornecedor mês a mês e como agrupar as datas por mês.', 0.2, 'Clicar numa célula da base → **Inserir > Tabela Dinâmica** → confirmar o intervalo → **Nova Planilha**. **Linhas: Fornecedor**; **Colunas: Data (agrupada por Mês)**; **Valores: Soma de Valor**. Agrupar: **botão direito numa data → Agrupar → Meses**.', 'Palavras-chave: Inserir > Tabela Dinâmica; Nova Planilha; Fornecedor em Linhas; Data/Meses em Colunas; Soma de Valor em Valores; Agrupar > Meses. Equivalentes aceitos: Fornecedor em Colunas e Mês em Linhas. Nota cheia (0,2): caminho, áreas e agrupamento. Metade (0,1): duas das três partes. Zero (0): Valor fora de Valores sem outra parte certa.'),
      (v_atividade, 16, 3, 'Explique como mostrar o valor como "% do Total Geral", o que os 58% do fornecedor Alfa indicam e que ação a área de compras deve propor; explique também por que as 40 compras novas não apareceram e como resolver.', 0.2, 'Botão direito num valor → **Mostrar Valores Como > % do Total Geral**. Os 58% mostram **concentração/dependência** de um só fornecedor (acima de 50%), um risco se ele atrasar; ação: **desenvolver/negociar outros fornecedores (diversificar)**. As compras novas não aparecem porque a tabela dinâmica usa um **cache** e **não atualiza sozinha**: botão direito → **Atualizar** (Alt+F5); para incluir novas linhas automaticamente, transformar a base em **Tabela oficial** (Inserir > Tabela).', 'Palavras-chave: Mostrar Valores Como; % do Total Geral; dependência acima de 50%; diversificar; cache; Atualizar/Alt+F5; Tabela oficial. Nota cheia (0,2): porcentagem, análise com ação e atualização. Metade (0,1): duas das três. Zero (0): uma ou nenhuma.'),
      (v_atividade, 17, 1, 'Explique como trocar o cálculo de Soma para Contagem e para Média e o que cada um responde.', 0.1, 'Botão direito num valor → **Resumir Valores Por** → **Contagem** (quantos pedidos foram emitidos de cada item) ou **Média** (valor médio/tíquete médio por pedido). (Máximo/Mínimo mostram picos e menores transações.)', 'Palavras-chave: Resumir Valores Por; Contagem = quantidade de pedidos; Média = valor médio. Nota cheia (0,1): caminho e o que cada um responde. Metade (0,05): só o caminho ou só os significados. Zero (0): nenhum.'),
      (v_atividade, 17, 2, 'Explique como criar um Campo Calculado para a armazenagem de 5% (caminho e fórmula) e por que ele não altera a base.', 0.2, '**Análise de Tabela Dinâmica > Campos, Itens e Conjuntos > Campo Calculado** → nome "Armazenagem" → fórmula **=''Valor'' * 0,05** → Adicionar. Ele **não altera a base** porque o cálculo existe só **dentro da tabela dinâmica** (que é uma visão/lente da base), e se atualiza quando entram novos dados.', 'Palavras-chave: Campo Calculado; Campos, Itens e Conjuntos; =''Valor''*0,05; não altera a base; só na tabela dinâmica. Nota cheia (0,2): caminho, fórmula e explicação. Metade (0,1): dois dos três. Zero (0): propõe criar coluna na base sem citar o campo calculado.'),
      (v_atividade, 17, 3, 'Explique como mostrar só os 10 itens de maior valor e como a Linha do Tempo permite analisar períodos (o que ela filtra e quais escalas oferece).', 0.2, 'Seta do campo Item → **Filtros de Valor > 10 Primeiros** (por Soma de Valor) e ordenar de forma **decrescente (Z-A)**. A **Linha do Tempo** (Inserir > Linha do Tempo, campo Data) é uma **barra horizontal com deslizador** que **filtra o período** da tabela/gráficos ligados; a escala alterna entre **Anos, Trimestres, Meses e Dias**, e basta arrastar as bordas do seletor.', 'Palavras-chave: 10 Primeiros; ordenação decrescente; Linha do Tempo; filtra por datas; deslizador; Anos/Trimestres/Meses/Dias. Nota cheia (0,2): filtro dos 10 e a linha do tempo explicada. Metade (0,1): só uma das partes. Zero (0): nenhuma.'),
      (v_atividade, 18, 1, 'Diga o tipo de gráfico ideal para a visão (1) e para a visão (2), justificando, explique os erros do colega (pizza com 12 fatias, efeito 3D e eixo começando em R$ 70.000) e diga como usar rótulos de dados no ranking.', 0.1, '(1) **Linhas** — evolução/tendência no tempo (mostra alta, estabilidade, retração ou sazonalidade). (2) **Barras (ou colunas)** ordenadas — comparação e ranking de categorias. Erros: **pizza** serve só para 2 a 4 fatias; o **3D distorce** as proporções; **eixo começando em R$ 70.000 (truncado)** exagera as diferenças — o eixo deve começar em zero. Rótulos: colocar **rótulos de dados na extremidade externa** das barras com o valor exato (moeda abreviada) e, com eles, pode-se **remover o eixo numérico** para despoluir.', 'Palavras-chave: linha = tendência; barras/colunas = ranking; pizza até 4 fatias; 3D distorce; eixo truncado/começar no zero; rótulos de dados na ponta das barras/remover eixo. Nota cheia (0,1): os dois gráficos, pelo menos dois erros e os rótulos. Metade (0,05): duas das três partes. Zero (0): uma ou nenhuma.'),
      (v_atividade, 18, 2, 'Diga qual gráfico usar na visão (3), o que fica em colunas, o que fica em linha e por que é preciso o eixo secundário.', 0.2, '**Gráfico combinado**: valor comprado (R$) em **colunas no eixo principal** (esquerda) e % do orçamento em **linha no eixo secundário** (direita). O eixo secundário é necessário porque as **escalas são muito diferentes** (centenas de milhares de reais × percentuais); no mesmo eixo, a linha ficaria **colada no zero**.', 'Palavras-chave: gráfico combinado; colunas = R$; linha = %; eixo secundário; escalas diferentes. Nota cheia (0,2): tipo, distribuição e motivo. Metade (0,1): tipo certo sem o motivo ou sem dizer o que é coluna/linha. Zero (0): outro tipo sem eixo secundário.'),
      (v_atividade, 18, 3, 'Explique como fazer uma única Segmentação de Dados por Fornecedor filtrar as duas tabelas dinâmicas ao mesmo tempo e como proteger a planilha sem travar os filtros e a segmentação.', 0.2, 'Inserir a **Segmentação de Dados** (campo Fornecedor) → botão direito → **Conexões de Relatório** → marcar as **duas tabelas dinâmicas**. Proteger: **Revisão > Proteger Planilha**, marcando **"Usar Tabela Dinâmica e Gráfico Dinâmico"** para filtros e segmentação continuarem funcionando (bloquear a aba da base e guardar a senha com o responsável).', 'Palavras-chave: Segmentação de Dados; Conexões de Relatório; duas tabelas; Proteger Planilha; "Usar Tabela Dinâmica e Gráfico Dinâmico". Nota cheia (0,2): conexão e proteção com a opção. Metade (0,1): só uma das partes. Zero (0): nenhuma.'),
      (v_atividade, 19, 1, 'Calcule o giro do estoque no trimestre, mostrando a fórmula (custo das saídas ÷ estoque médio), e explique o que esse número significa.', 0.1, 'Giro = R$ 150.000 ÷ R$ 50.000 = **3 vezes no trimestre**: o estoque médio foi **consumido/renovado 3 vezes** no período; quanto maior o giro, menos dinheiro parado.', 'Palavras-chave: 150.000 ÷ 50.000; 3 vezes; renovado/consumido; dinheiro parado. Nota cheia (0,1): conta, resultado e significado. Metade (0,05): só a conta com o resultado. Zero (0): resultado errado.'),
      (v_atividade, 19, 2, 'Calcule a ruptura (requisições não atendidas ÷ total de requisições) e a cobertura das luvas (saldo ÷ consumo médio diário) e diga a cor do semáforo de cada KPI em relação à meta.', 0.2, 'Ruptura = 30 ÷ 500 = **6%**: acima da meta de 5% → **vermelho**. Cobertura = 900 ÷ 150 = **6 dias**: abaixo do mínimo de 10 dias → **vermelho (alerta)**.', 'Palavras-chave: 30 ÷ 500; 6%; acima de 5%; vermelho; 900 ÷ 150; 6 dias; abaixo de 10. Equivalentes aceitos: amarelo para a cobertura, se justificado como alerta. Nota cheia (0,2): os dois KPIs com semáforo. Metade (0,1): um KPI completo, ou os dois sem semáforo. Zero (0): nenhum.'),
      (v_atividade, 19, 3, 'Conte a história desses dados em 4 passos (Pergunta → Dado → Conclusão → Ação) para apresentar à gerência a falta de luvas e diga por onde começar a fala numa apresentação para a diretoria.', 0.2, '**Pergunta:** por que faltaram luvas no mês? **Dado:** ruptura de 6% (meta 5%) e cobertura de 6 dias (meta 10). **Conclusão:** o estoque mínimo de luvas está abaixo do consumo real. **Ação:** subir o mínimo para cobrir pelo menos 10 dias (10 × 150 = 1.500 pares) e acompanhar a ruptura no dashboard. Para a diretoria, **começar pela conclusão** (o impacto, ex.: "a falta de luvas vem de um estoque mínimo baixo") e só depois mostrar o gráfico que comprova, sem explicar fórmulas.', 'Palavras-chave: Pergunta; Dado (6% e 6 dias); Conclusão; Ação (subir o mínimo/1.500 pares); começar pela conclusão/impacto, não pelas fórmulas. Nota cheia (0,2): os 4 passos com os números e a abertura pela conclusão. Metade (0,1): os 4 passos sem a abertura, ou 2 a 3 passos com a abertura. Zero (0): sem a estrutura.'),
      (v_atividade, 20, 1, 'Diga as três abas em que o arquivo deve ser dividido, o que fica em cada uma, a ordem certa de construção do dashboard e por que fazer antes um rascunho (wireframe) no papel.', 0.1, '**Base_Dados** (dados brutos), **Calculos_Apoio** (tabelas dinâmicas que alimentam os gráficos) e **Dashboard** (tela final limpa e interativa). Ordem: 1) organizar e validar a base; 2) criar as tabelas dinâmicas de apoio; 3) criar os gráficos dinâmicos e levá-los ao Dashboard; 4) inserir segmentadores e ligá-los por Conexões de Relatório. O **rascunho (wireframe) no papel** define antes onde ficam KPIs, gráficos e filtros e **evita retrabalho** no software.', 'Palavras-chave: Base_Dados; Calculos_Apoio; Dashboard; base → tabelas → gráficos → segmentadores; wireframe/rascunho evita retrabalho. Nota cheia (0,1): abas, ordem e o motivo do rascunho. Metade (0,05): duas das três partes. Zero (0): uma ou nenhuma.'),
      (v_atividade, 20, 2, 'Descreva onde ficam os cartões de KPI, os gráficos centrais e os filtros pelo padrão de leitura em Z e quais são as três informações de um cartão de KPI.', 0.2, 'Padrão em **Z**: **topo** = cartões de KPI (lidos primeiro, da esquerda para a direita); **centro** = gráficos de tendência/comparação; **base** = detalhes e rankings; filtros/segmentadores numa **barra no topo ou na lateral**. Cartão de KPI: **rótulo** (nome do indicador), **número grande** e **tendência** (seta de alta ou baixa).', 'Palavras-chave: padrão em Z; KPIs no topo; gráficos no centro; detalhes na base; filtros no topo/lateral; rótulo, número, tendência. Nota cheia (0,2): posições e as três informações. Metade (0,1): só uma das partes. Zero (0): nenhuma.'),
      (v_atividade, 20, 3, 'Corrija os erros de design do colega (quantidade de gráficos, cores, 3D, alinhamento, linhas de grade e demais elementos da planilha na tela final) e justifique por que um painel com menos gráficos gera decisões mais rápidas.', 0.2, 'Reduzir para cerca de **4 gráficos** (no máximo 7 métricas) e levar o resto para um segundo painel; **paleta sóbria** (azul/cinza), **verde = meta atingida**, **vermelho só para alertas**; trocar **3D por 2D**; **alinhar** os gráficos (Alinhar, Distribuir, Ajustar à grade/Alt); na tela final, **ocultar linhas de grade, barra de fórmulas, cabeçalhos e botões de campo dos gráficos** (Exibir). Menos gráficos geram decisões mais rápidas porque evitam a **sobrecarga cognitiva**: quando tudo é destacado, nada se destaca.', 'Palavras-chave: poucos gráficos (até 4 ou 7 métricas); cores sóbrias, verde/vermelho para status; sem 3D; alinhar; ocultar linhas de grade/barra de fórmulas/cabeçalhos/botões de campo; sobrecarga cognitiva. Nota cheia (0,2): corrige pelo menos quatro erros e justifica. Metade (0,1): corrige parte dos erros, ou só justifica. Zero (0): nenhum.');
end $$;
